  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class RoomType {
  + Type : string
}

class HotelOffer {
  + Price : float
  + Rating : int
  + CityArea : string
  + Preferences : string[]
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : float
  + CityArea : string
  + HotelRating : int
  + Preferences : string[]
}

class SpecialOffer {
  + Price : float
}

class Booking {
  + BookingIdentifier : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MaxBudget : float
  + CancellationDeadline : date
  + IsPrepaid : boolean
  + IsConfirmed : boolean
  + IsCancelled : boolean
}

class CreditCardInfo {
  + CardNumber : string
}

Hotel "0..*" -- "0..1" HotelChain
Hotel "0..*" -- "1" City
Hotel "1" -- "0..*" HotelOffer
Hotel "1" -- "0..*" Booking
Hotel "1" -- "0..*" SpecialOffer
Traveller "1" -- "0..*" Booking
Traveller "1" -- "0..*" PreliminaryBooking
Traveller "1" -- "0..*" SpecialOffer
Traveller "1" -- "0..1" CreditCardInfo
PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "0..1" Booking
Booking "1" -- "1" CreditCardInfo
Booking "1" -- "1" RoomType

@enduml

